def flag_tapes(apps, schema_editor):
    """Imports used to write "tape" first in the note ("tape" or "tape; with X"): move it to is_tape."""
    SetlistSong = apps.get_model("events", "SetlistSong")
    for entry in SetlistSong.objects.filter(note__startswith="tape"):
        parts = [p.strip() for p in entry.note.split(";")]
        if parts[0] != "tape":
            continue
        entry.is_tape = True
        entry.note = "; ".join(parts[1:])
        entry.save(update_fields=["is_tape", "note"])


